INSERT INTO public.posts VALUES ('55d04f17-e48d-4bc1-ab47-3857142f8fe8', '95377818-812e-49f1-afe8-3a5f6146c516', 'apple', 'Apple', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An ", "type": "text"}, {"text": "apple", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a round, sweet or slightly tart fruit that grows on apple trees. It comes in varieties such as ", "type": "text"}, {"text": "Red Delicious, Granny Smith, Fuji, and Gala", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Apples are commonly eaten fresh, used in ", "type": "text"}, {"text": "pies, juices, smoothies, salads, sauces", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and other dishes. They are a good source of ", "type": "text"}, {"text": "fiber, vitamin C, and antioxidants", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}', 'Apple is a fruit', '/uploads/1786965136026-d9ef6e4a819263fe.png', 1, 57, 'published', '2026-08-17 11:12:35.404532+00', 0, 1, 1, false, '2026-08-17 11:12:35.404532+00', '2026-08-17 11:12:35.404532+00', 0, '["Food"]', '''antioxid'':103 ''appl'':1A,3C,18,36,66 ''bold'':23,58,85,108 ''c'':101 ''come'':39 ''common'':68 ''content'':9,12,64 ''delici'':48 ''dish'':89 ''doc'':8 ''eaten'':69 ''fiber'':99 ''food'':2B ''fresh'':70 ''fruit'':6C,32 ''fuji'':51 ''gala'':53 ''good'':93 ''granni'':49 ''grow'':34 ''juic'':77 ''mark'':21,56,83,106 ''paragraph'':11,63 ''pie'':76 ''red'':47 ''round'':27 ''salad'':79 ''sauc'':80 ''slight'':30 ''smith'':50 ''smoothi'':78 ''sourc'':94 ''sweet'':28 ''tart'':31 ''text'':13,16,17,20,24,45,46,55,59,61,65,74,75,82,86,97,98,105,109,111 ''tree'':37 ''type'':7,10,15,19,22,44,54,57,60,62,73,81,84,96,104,107,110 ''use'':71 ''varieti'':41 ''vitamin'':100', 9, NULL);
INSERT INTO public.posts VALUES ('f48f36ab-1b7e-4dd8-8dd6-5413280c8e0a', '434b46d6-532b-4a50-abde-2c65e9690f82', 'my-response-to-ai-cybersecurity', 'My Response to AI Cybersecurity', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "This is my response...", "type": "text"}]}]}', 'A response to the AI post', '', 1, 4, 'published', '2026-08-18 06:42:31.224798+00', 0, 0, 0, false, '2026-08-18 06:42:31.224798+00', '2026-08-18 06:42:31.224798+00', 0, '[]', '''ai'':4A,10C ''content'':14,17 ''cybersecur'':5A ''doc'':13 ''paragraph'':16 ''post'':11C ''respons'':2A,7C,22 ''text'':18,24 ''type'':12,15,23', 0, '10000000-0000-0000-0000-000000000001');
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000005', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'understanding-large-language-models', 'Understanding Large Language Models', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Large language models are neural networks trained on vast amounts of text to predict the next word in a sequence. This simple objective, scaled to billions of parameters, produces systems that can write, summarize, translate, and reason in ways that feel remarkably human. Understanding how they work helps demystify both their strengths and their limitations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These models do not truly understand language the way people do. They learn statistical patterns and associations, which is why they can be fluent yet occasionally wrong. Techniques such as fine-tuning, reinforcement learning from human feedback, and retrieval augmentation improve their usefulness and alignment with human intent.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As models grow more capable, the focus is shifting from raw scale to efficiency, safety, and specialization. Smaller, domain-specific models are becoming practical for many tasks, making the technology more accessible and affordable for organizations of every size.", "type": "text"}]}]}', 'A clear introduction to how LLMs work and what they can and cannot do.', 'https://images.unsplash.com/photo-1531746790731-6c087fecd65a?w=800&q=80', 5, 1040, 'published', '2026-08-12 06:56:07.542587+00', 260, 38, 3, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["AI"]', '''access'':174 ''afford'':176 ''ai'':5B ''align'':132 ''amount'':35 ''associ'':103 ''augment'':127 ''becom'':165 ''billion'':51 ''cannot'':18C ''capabl'':146 ''clear'':7C ''content'':21,24,85,140 ''demystifi'':74 ''doc'':20 ''domain'':161 ''domain-specif'':160 ''effici'':155 ''everi'':180 ''feedback'':124 ''feel'':66 ''fine'':118 ''fine-tun'':117 ''fluent'':110 ''focus'':148 ''grow'':144 ''help'':73 ''human'':68,123,134 ''improv'':128 ''intent'':135 ''introduct'':8C ''languag'':3A,27,93 ''larg'':2A,26 ''learn'':99,121 ''limit'':80 ''llms'':11C ''make'':170 ''mani'':168 ''model'':4A,28,88,143,163 ''network'':31 ''neural'':30 ''next'':41 ''object'':48 ''occasion'':112 ''organ'':178 ''paragraph'':23,84,139 ''paramet'':53 ''pattern'':101 ''peopl'':96 ''practic'':166 ''predict'':39 ''produc'':54 ''raw'':152 ''reason'':62 ''reinforc'':120 ''remark'':67 ''retriev'':126 ''safeti'':156 ''scale'':49,153 ''sequenc'':45 ''shift'':150 ''simpl'':47 ''size'':181 ''smaller'':159 ''special'':158 ''specif'':162 ''statist'':100 ''strength'':77 ''summar'':59 ''system'':55 ''task'':169 ''techniqu'':114 ''technolog'':172 ''text'':25,37,82,86,137,141,183 ''train'':32 ''translat'':60 ''truli'':91 ''tune'':119 ''type'':19,22,81,83,136,138,182 ''understand'':1A,69,92 ''use'':130 ''vast'':34 ''way'':64,95 ''word'':42 ''work'':12C,72 ''write'':58 ''wrong'':113 ''yet'':111', 0, NULL);
INSERT INTO public.posts VALUES ('6a2932a3-1023-45b7-b683-4f67f8ebcc42', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-importance-of-content-writing-in-the-digital-world', 'The Importance of Content Writing in the Digital World', '{"type": "doc", "content": [{"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Content writing has become an essential part of the digital world. Every website, blog, social media platform, and online business depends on useful and engaging content to communicate with its audience. Good content does more than provide information; it helps businesses build trust, explain their products, answer customer questions, and create a stronger connection with readers.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Effective content writing starts with understanding the audience. A writer needs to know what readers are looking for and present information in a clear and interesting way. Whether the content is a technical article, product description, social media post, or educational blog, the writing should have a clear purpose. Simple language, meaningful headings, relevant examples, and a logical structure can make content easier to understand and more engaging.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Content writing also plays an important role in search engine optimization. Well-structured articles with relevant topics and useful information can help websites become more visible in search results. However, writing only for search engines is not enough. The best content focuses on providing genuine value to readers while naturally incorporating relevant keywords.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As digital platforms continue to grow, the demand for high-quality content will continue to increase. AI tools are also changing the content-writing process by helping with research, brainstorming, editing, and content generation. However, human creativity, originality, context, and judgment remain important for producing content that feels authentic and useful. The future of content writing will likely combine human creativity with intelligent technology to create better digital experiences.", "type": "text"}]}]}', 'importance of content writing', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&q=80', 2, 243, 'published', '2026-08-17 07:23:00.527005+00', 0, 0, 0, false, '2026-08-17 07:23:00.527005+00', '2026-08-17 07:23:00.527005+00', 0, '["Writing"]', '''ai'':237 ''also'':162,240 ''answer'':70 ''articl'':119,174 ''audienc'':54,93 ''authent'':270 ''becom'':27,184 ''best'':200 ''better'':288 ''blog'':37,127 ''brainstorm'':251 ''build'':65 ''busi'':43,64 ''chang'':241 ''clear'':109,133 ''combin'':280 ''communic'':51 ''connect'':77 ''content'':4A,13C,17,22,24,49,56,84,87,115,147,158,160,201,218,232,244,254,267,276 ''content-writ'':243 ''context'':260 ''continu'':223,234 ''creat'':74,287 ''creativ'':258,282 ''custom'':71 ''demand'':227 ''depend'':44 ''descript'':121 ''digit'':8A,33,221,289 ''doc'':16 ''easier'':148 ''edit'':252 ''educ'':126 ''effect'':86 ''engag'':48,153 ''engin'':169,195 ''enough'':198 ''essenti'':29 ''everi'':35 ''exampl'':140 ''experi'':290 ''explain'':67 ''feel'':269 ''focus'':202 ''futur'':274 ''generat'':255 ''genuin'':205 ''good'':55 ''grow'':225 ''head'':138 ''help'':63,182,248 ''high'':230 ''high-qual'':229 ''howev'':190,256 ''human'':257,281 ''import'':2A,11C,165,264 ''incorpor'':211 ''increas'':236 ''inform'':61,106,180 ''intellig'':284 ''interest'':111 ''judgment'':262 ''keyword'':213 ''know'':98 ''languag'':136 ''like'':279 ''logic'':143 ''look'':102 ''make'':146 ''meaning'':137 ''media'':39,123 ''natur'':210 ''need'':96 ''onlin'':42 ''optim'':170 ''origin'':259 ''paragraph'':19,21,83,157,217 ''part'':30 ''platform'':40,222 ''play'':163 ''post'':124 ''present'':105 ''process'':246 ''produc'':266 ''product'':69,120 ''provid'':60,204 ''purpos'':134 ''qualiti'':231 ''question'':72 ''reader'':79,100,208 ''relev'':139,176,212 ''remain'':263 ''research'':250 ''result'':189 ''role'':166 ''search'':168,188,194 ''simpl'':135 ''social'':38,122 ''start'':89 ''stronger'':76 ''structur'':144,173 ''technic'':118 ''technolog'':285 ''text'':23,81,85,155,159,215,219,292 ''tool'':238 ''topic'':177 ''trust'':66 ''type'':15,18,20,80,82,154,156,214,216,291 ''understand'':91,150 ''use'':46,179,272 ''valu'':206 ''visibl'':186 ''way'':112 ''websit'':36,183 ''well'':172 ''well-structur'':171 ''whether'':113 ''world'':9A,34 ''write'':5A,10B,14C,25,88,129,161,191,245,277 ''writer'':95', 0, NULL);
INSERT INTO public.posts VALUES ('dcc530d2-dda4-43f7-891c-f394493e7a15', '95377818-812e-49f1-afe8-3a5f6146c516', 'the-science-of-why-the-human-brain-needs-sleep', 'The Science of Why the Human Brain Needs Sleep', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sleep may seem like a period when the body simply rests, but science shows that the brain remains highly active during sleep. Every night, the brain performs several important processes that help us remember information, regulate emotions, and maintain overall health.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "One of the most important functions of sleep is ", "type": "text"}, {"text": "memory consolidation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". During the day, we collect enormous amounts of information through studying, working, and interacting with our surroundings. While we sleep, the brain processes and organizes some of this information. Certain memories are strengthened, making it easier to recall what we learned later.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sleep also plays an important role in ", "type": "text"}, {"text": "brain maintenance", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". During sleep, the brain''s waste-clearance system becomes more active and helps remove metabolic waste products that accumulate during waking hours. This process is one reason researchers consider healthy sleep important for long-term brain health.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Another fascinating aspect of sleep is its connection to ", "type": "text"}, {"text": "emotions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Insufficient sleep can make people more irritable, stressed, or emotionally reactive. Adequate sleep, on the other hand, helps the brain regulate emotional responses and deal with everyday challenges more effectively.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sleep also affects the rest of the body. It contributes to immune function, hormone regulation, metabolism, and physical recovery. This means that sleep is not simply \"downtime\"ΓÇöit is an essential biological process.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Scientists continue to study sleep because many questions remain unanswered. Why do we dream? Why do different species require different amounts of sleep? How exactly does the brain decide which memories to preserve? Research into these questions could lead to better treatments for sleep disorders and improve our understanding of the human brain.", "type": "text"}]}, {"type": "paragraph"}]}', 'Sleep may seem like a period when the body simply rests, but science shows that the brain remains highly active during sleep. Every night, the brain performs...', '/uploads/1787044519902-6b96d8f5e279258e.png', 2, 265, 'published', '2026-08-18 09:15:33.241188+00', 0, 0, 0, false, '2026-08-18 09:15:33.241188+00', '2026-08-18 17:24:12.00924+00', 0, '["Science"]', '''accumul'':197 ''activ'':30C,64,189 ''adequ'':253 ''affect'':280 ''also'':161,279 ''amount'':118,337 ''anoth'':223 ''aspect'':225 ''becom'':187 ''better'':357 ''biolog'':309 ''bodi'':19C,53,285 ''bold'':110,176,240 ''brain'':7A,27C,36C,61,70,133,170,181,215,261,344,369 ''certain'':141 ''challeng'':269 ''clearanc'':185 ''collect'':116 ''connect'':230 ''consid'':207 ''consolid'':105 ''content'':40,43,90,158,221,276,315 ''continu'':318 ''contribut'':287 ''could'':354 ''day'':114 ''deal'':266 ''decid'':345 ''differ'':333,336 ''disord'':361 ''doc'':39 ''downtim'':304 ''dream'':330 ''easier'':147 ''effect'':271 ''emot'':81,235,251,263 ''enorm'':117 ''essenti'':308 ''everi'':33C,67 ''everyday'':268 ''exact'':341 ''fascin'':224 ''function'':97,290 ''hand'':258 ''health'':85,216 ''healthi'':208 ''help'':76,191,259 ''high'':29C,63 ''hormon'':291 ''hour'':200 ''human'':6A,368 ''immun'':289 ''import'':73,96,164,210 ''impr