INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000006', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-art-of-fermentation-a-beginners-guide', 'The Art of Fermentation: A Beginner''s Guide', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fermentation is one of the oldest food preservation techniques, and it is enjoying a well-deserved revival. From sauerkraut and kimchi to yogurt and sourdough, fermentation transforms simple ingredients into complex, flavorful, and nutritious foods. The process relies on beneficial bacteria and yeasts that break down sugars and starches over time.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Getting started is easier than most people expect. A basic vegetable ferment needs only vegetables, salt, water, and a clean jar. The salt creates an environment where good bacteria thrive while harmful ones are suppressed. Within days, the mixture develops a tangy flavor and a satisfying crunch.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Beyond flavor, fermented foods support gut health by introducing live cultures and making nutrients more bioavailable. Start small, keep everything clean, and taste as you go. With a little patience, fermentation becomes a rewarding kitchen habit.", "type": "text"}]}]}', 'A gentle introduction to making your own fermented foods at home.', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&q=80', 4, 900, 'published', '2026-08-16 06:56:07.542587+00', 190, 30, 5, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Food"]', '''art'':2A ''bacteria'':69,114 ''basic'':95 ''becom'':170 ''beginn'':6A ''benefici'':68 ''beyond'':139 ''bioavail'':154 ''break'':73 ''clean'':105,159 ''complex'':59 ''content'':23,26,84,137 ''creat'':109 ''crunch'':132 ''cultur'':149 ''day'':122 ''deserv'':44 ''develop'':125 ''doc'':22 ''easier'':89 ''enjoy'':40 ''environ'':111 ''everyth'':158 ''expect'':93 ''ferment''