INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000007', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'exploring-regional-indian-cuisines', 'Exploring Regional Indian Cuisines', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Indian cuisine is far more diverse than the handful of dishes most people know. Each region has its own ingredients, techniques, and flavor profiles shaped by climate, geography, and history. From the coconut-rich curries of the south to the mustard-oil cooking of the east, the variety is astonishing.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The north is known for tandoori cooking, rich gravies, and wheat-based breads, while the west offers both the vegetarian thalis of Gujarat and the seafood of the Konkan coast. The south relies heavily on rice, lentils, and fermented batters for dishes like dosa and idli. The northeast brings bamboo shoots, fermented soybeans, and fresh herbs into the mix.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Exploring regional cuisines is a journey through the country itself. Each dish tells a story about the people, the land, and centuries of culinary tradition. The best way to appreciate it is to cook and taste widely, one region at a time.", "type": "text"}]}]}', 'A tour of the diverse regional cooking traditions of India.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&q=80', 4, 950, 'published', '2026-08-15 06:56:07.542587+00', 220, 35, 6, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Food"]', '''appreci'':176 ''astonish'':74 ''bamboo'':131 ''base'':93 ''batter'':121 ''best'':173 ''bread'':94 ''bring'':130 ''centuri'':168 ''climat'':49 ''coast'':111 ''coconut'':56 ''coconut-rich'':55 ''content'':18,21,79,145 ''cook'':12C,67,87,180 ''countri'':155 ''cuisin'':4A,24,149 ''culinari'':170 ''curri'':58 ''dish'':33,123,158 ''divers'':10C,28 ''doc'':17 ''dosa'':125 ''east'':70 ''explor'':1A,147 ''far'':26 ''ferment'':120,133 ''flavor'':45 ''food'':5B ''fresh'':136 ''geographi'':50 ''gravi'':89 ''gujarat'':104 ''hand'':31 ''heavili'':115 ''herb'':137 ''histori'':52 ''id'':127 ''india'':15C ''indian'':3A,23 ''ingredi'':42 ''journey'':152 ''know'':36 ''known'':84 ''konkan'':110 ''land'':166 ''lentil'':118 ''like'':124 ''mix'':140 ''mustard'':65 ''mustard-oil'':64 ''north'':82 ''northeast'':129 ''offer'':98 ''oil'':66 ''one'':184 ''paragraph'':20,78,144 ''peopl'':35,164 ''profil'':46 ''region'':2A,11C,38,148,185 ''reli'':114 ''rice'':117 ''rich'':57,88 ''seafood'':107 ''shape'':47 ''shoot'':132 ''south'':61,113 ''soybean'':134 ''stori'':161 ''tandoori'':86 ''tast'':182 ''techniqu'':43 ''tell'':159 ''text'':22,76,80,142,146,190 ''thali'':102 ''time'':188 ''tour'':7C ''tradit'':13C,171 ''type'':16,19,75,77,141,143,189 ''varieti'':72 ''vegetarian'':101 ''way'':174 ''west'':97 ''wheat'':92 ''wheat-bas'':91 ''wide'':183', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000008', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'the-science-of-perfect-sourdough-bread', 'The Science of Perfect Sourdough Bread', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sourdough bread is a beautiful intersection of biology and chemistry. A living starter of wild yeast and lactic acid bacteria ferments the dough, producing the carbon dioxide that leavens the bread and the acids that give it its signature tang. Understanding this process is the key to consistent results.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The strength of the dough comes from gluten, a network of proteins that traps gas and gives bread its structure. Hydration, folding, and time all influence how that network develops. Temperature controls the pace of fermentation, which in turn shapes both flavor and crumb.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Baking is the final transformation. The intense heat of a preheated oven, often with steam, causes the dough to spring upward before the crust sets. With practice and careful observation, home bakers can produce loaves that rival any bakery.", "type": "text"}]}]}', 'The biology and chemistry behind a great loaf of sourdough.', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&q=80', 4, 920, 'published', '2026-08-14 06:56:07.542587+00', 240, 40, 4, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Food"]', '''acid'':43,58 ''bacteria'':44 ''bake'':130 ''baker'':161 ''bakeri'':168 ''beauti'':29 ''behind'':12C ''biolog'':9C,32 ''bread'':6A,26,55,97 ''carbon'':50 ''care'':158 ''caus'':145 ''chemistri'':11C,34 ''come'':85 ''consist'':72 ''content'':20,23,78,128 ''control'':111 ''crumb'':123 ''crust'':153 ''develop'':109 ''dioxid'':51 ''doc'':19 ''dough'':47,84,147 ''ferment'':45,115 ''final'':133 ''flavor'':121 ''fold'':101 ''food'':7B ''gas'':94 ''give'':60,96 ''gluten'':87 ''great'':14C ''heat'':137 ''home'':160 ''hydrat'':100 ''influenc'':105 ''intens'':136 ''intersect'':30 ''key'':70 ''lactic'':42 ''leaven'':53 ''live'':36 ''loaf'':15C ''loav'':164 ''network'':89,108 ''observ'':159 ''often'':142 ''oven'':141 ''pace'':113 ''paragraph'':22,77,127 ''perfect'':4A ''practic'':156 ''preheat'':140 ''process'':67 ''produc'':48,163 ''protein'':91 ''result'':73 ''rival'':166 ''scienc'':2A ''set'':154 ''shape'':119 ''signatur'':63 ''sourdough'':5A,17C,25 ''spring'':149 ''starter'':37 ''steam'':144 ''strength'':81 ''structur'':99 ''tang'':64 ''temperatur'':110 ''text'':24,75,79,125,129,170 ''time'':103 ''transform'':134 ''trap'':93 ''turn'':118 ''type'':18,21,74,76,124,126,169 ''understand'':65 ''upward'':150 ''wild'':39 ''yeast'':40', 0, NULL);
