INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000009', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'plant-based-cooking-myths-and-realities', 'Plant-Based Cooking: Myths and Realities', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Plant-based eating has moved from the fringe to the mainstream, but it is surrounded by misconceptions. One common myth is that plant-based food is bland or unsatisfying. In reality, a well-prepared plant-based meal can be just as rich and varied as any other, drawing on legumes, grains, nuts, and a world of spices.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Another myth is that plant-based diets are automatically healthy. Processed meat substitutes can be high in sodium and additives, just like any processed food. The healthiest approach focuses on whole foods: beans, lentils, vegetables, fruits, and whole grains prepared with care.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The key to great plant-based cooking is technique. Roasting, caramelizing, and layering umami-rich ingredients like mushrooms, miso, and nutritional yeast create depth of flavor. With the right approach, plant-based meals are not a compromise but a delicious choice in their own right.", "type": "text"}]}]}', 'Separating fact from fiction in plant-based cooking.', 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800&q=80', 4, 880, 'published', '2026-08-13 06:56:07.542587+00', 180, 28, 3, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Food"]', '''addit'':112 ''anoth'':92 ''approach'':120,172 ''automat'':101 ''base'':3A,16C,27,50,64,98,147,175 ''bean'':125 ''bland'':53 ''caramel'':152 ''care'':134 ''choic'':184 ''common'':44 ''compromis'':180 ''content'':20,23,90,139 ''cook'':4A,17C,148 ''creat'':165 ''delici'':183 ''depth'':166 ''diet'':99 ''doc'':19 ''draw'':76 ''eat'':28 ''fact'':10C ''fiction'':12C ''flavor'':168 ''focus'':121 ''food'':8B,51,117,124 ''fring'':33 ''fruit'':128 ''grain'':79,131 ''great'':144 ''healthi'':102 ''healthiest'':119 ''high'':108 ''ingredi'':158 ''key'':142 ''layer'':154 ''legum'':78 ''lentil'':126 ''like'':114,159 ''mainstream'':36 ''meal'':65,176 ''meat'':104 ''misconcept'':42 ''miso'':161 ''move'':30 ''mushroom'':160 ''myth'':5A,45,93 ''nut'':80 ''nutrit'':163 ''one'':43 ''paragraph'':22,89,138 ''plant'':2A,15C,26,49,63,97,146,174 ''plant-bas'':1A,14C,25,48,62,96,145,173 ''prepar'':61,132 ''process'':103,116 ''realiti'':7A,57 ''rich'':70,157 ''right'':171,188 ''roast'':151 ''separ'':9C ''sodium'':110 ''spice'':85 ''substitut'':105 ''surround'':40 ''techniqu'':150 ''text'':24,87,91,136,140,190 ''type'':18,21,86,88,135,137,189 ''umami'':156 ''umami-rich'':155 ''unsatisfi'':55 ''vari'':72 ''veget'':127 ''well'':60 ''well-prepar'':59 ''whole'':123,130 ''world'':83 ''yeast'':164', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000010', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'street-food-around-the-world', 'Street Food Around the World', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Street food is the most direct expression of a culture''s everyday cooking. It is fast, affordable, and deeply rooted in local ingredients and traditions. From the taco stands of Mexico to the night markets of Taiwan, street food offers a window into how people actually eat.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Each region has its icons. Thailand is famous for pad thai and mango sticky rice, Vietnam for banh mi and pho, and India for chaat, vada pav, and dosa. In the Middle East, falafel and shawarma reign, while Latin America offers arepas, empanadas, and elote.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What makes street food special is its immediacy. Dishes are cooked to order, often by vendors who have perfected a single recipe over decades. For travelers and locals alike, a great street food stall is a reminder that some of the best meals in the world are also the most humble.", "type": "text"}]}]}', 'A global tour of the world''s most beloved street foods.', 'https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=800&q=80', 4, 910, 'published', '2026-08-12 06:56:07.542587+00', 300, 45, 8, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Food"]', '''actual'':70 ''afford'':41 ''alik'':157 ''also'':176 ''america'':117 ''arepa'':119 ''around'':3A ''banh'':95 ''belov'':15C ''best'':170 ''chaat'':102 ''content'':20,23,76,127 ''cook'':37,139 ''cultur'':34 ''decad'':152 ''deepli'':43 ''direct'':30 ''dish'':137 ''doc'':19 ''dosa'':106 ''east'':110 ''eat'':71 ''elot'':122 ''empanada'':120 ''everyday'':36 ''express'':31 ''falafel'':111 ''famous'':85 ''fast'':40 ''food'':2A,6B,17C,26,63,132,161 ''global'':8C ''great'':159 ''humbl'':179 ''icon'':82 ''immediaci'':136 ''india'':100 ''ingredi'':47 ''latin'':116 ''local'':46,156 ''make'':130 ''mango'':90 ''market'':59 ''meal'':171 ''mexico'':55 ''mi'':96 ''middl'':109 ''night'':58 ''offer'':64,118 ''often'':142 ''order'':141 ''pad'':87 ''paragraph'':22,75,126 ''pav'':104 ''peopl'':69 ''perfect'':147 ''pho'':98 ''recip'':150 ''region'':79 ''reign'':114 ''remind'':165 ''rice'':92 ''root'':44 ''shawarma'':113 ''singl'':149 ''special'':133 ''stall'':162 ''stand'':53 ''sticki'':91 ''street'':1A,16C,25,62,131,160 ''taco'':52 ''taiwan'':61 ''text'':24,73,77,124,128,181 ''thai'':88 ''thailand'':83 ''tour'':9C ''tradit'':49 ''travel'':154 ''type'':18,21,72,74,123,125,180 ''vada'':103 ''vendor'':144 ''vietnam'':93 ''window'':66 ''world'':5A,12C,174', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000011', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'the-rise-of-edge-computing', 'The Rise of Edge Computing', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Edge computing moves data processing closer to where data is generated, rather than sending everything to a centralized cloud. This matters for applications that need low latency, such as autonomous vehicles, industrial automation, and real-time video analytics. By processing data locally, edge systems can respond in milliseconds.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The growth of the Internet of Things has made edge computing essential. Billions of sensors and devices generate data that would be impractical to transmit and process centrally. Edge nodes filter, aggregate, and analyze this data on site, sending only the most important information to the cloud.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Edge computing also improves reliability and privacy. Applications can continue to function even when connectivity is limited, and sensitive data can be processed locally without leaving the premises. As devices become more capable, the boundary between edge and cloud will continue to blur.", "type": "text"}]}]}', 'Why processing data closer to the source is reshaping infrastructure.', 'https://images.unsplash.com/photo-1541185934-01b600ea069c?w=800&q=80', 5, 1000, 'published', '2026-08-16 06:56:07.542587+00', 270, 43, 5, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Technology"]', '''aggreg'':110 ''also'':134 ''analyt'':62 ''analyz'':112 ''applic'':46,139 ''autom'':56 ''autonom'':53 ''becom'':162 ''billion'':91 ''blur'':174 ''boundari'':166 ''capabl'':164 ''central'':41,106 ''closer'':10C,29 ''cloud'':42,125,170 ''comput'':5A,25,89,133 ''connect'':146 ''content'':19,22,77,130 ''continu'':141,172 ''data'':9C,27,32,65,97,114,151 ''devic'':95,161 ''doc'':18 ''edg'':4A,24,67,88,107,132,168 ''essenti'':90 ''even'':144 ''everyth'':38 ''filter'':109 ''function'':143 ''generat'':34,96 ''growth'':80 ''import'':121 ''impract'':101 ''improv'':135 ''industri'':55 ''inform'':122 ''infrastructur'':16C ''internet'':83 ''latenc'':50 ''leav'':157 ''limit'':148 ''local'':66,155 ''low'':49 ''made'':87 ''matter'':44 ''millisecond'':72 ''move'':26 ''need'':48 ''node'':108 ''paragraph'':21,76,129 ''premis'':159 ''privaci'':138 ''process'':8C,28,64,105,154 ''rather'':35 ''real'':59 ''real-tim'':58 ''reliabl'':136 ''reshap'':15C ''respond'':70 ''rise'':2A ''send'':37,117 ''sensit'':150 ''sensor'':93 ''site'':116 ''sourc'':13C ''system'':68 ''technolog'':6B ''text'':23,74,78,127,131,176 ''thing'':85 ''time'':60 ''transmit'':103 ''type'':17,20,73,75,126,128,175 ''vehicl'':54 ''video'':61 ''without'':156 ''would'':99', 0, NULL);
INSERT INTO public.posts VALUES ('95909996-f66a-470d-b166-3c8a78f1e7b3', '2c8b7b50-5b68-4d03-b4ff-c8145ff2d1da', 'flow-test-2-post', 'Flow Test 2 Post', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Test", "type": "text"}]}]}', 'Test', '', 1, 1, 'draft', NULL, 0, 0, 1, false, '2026-08-18 11:33:57.596531+00', '2026-08-18 11:33:57.596531+00', 1, '[]', '''2'':3A ''content'':8,11 ''doc'':7 ''flow'':1A ''paragraph'':10 ''post'':4A ''test'':2A,5C,13 ''text'':12,15 ''type'':6,9,14', 1, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000002', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'building-reliable-ai-powered-applications', 'Building Reliable AI-Powered Applications', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Building applications that rely on large language models introduces a new set of engineering challenges. Unlike traditional software, model outputs are probabilistic, which means the same input can produce different results. Reliability therefore depends on careful prompt design, output validation, and graceful fallback strategies when the model is uncertain.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A robust AI application separates the model from the business logic. Retrieval-augmented generation, structured outputs, and evaluation pipelines help keep responses grounded and consistent. Monitoring is equally important: tracking latency, cost, and quality over time lets teams catch regressions before users do.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Finally, treat AI like any other dependency. Version your prompts, test against golden datasets, and design for observability from day one. The teams that succeed are the ones that apply disciplined software engineering practices to an inherently nondeterministic technology.", "type": "text"}]}]}', 'Engineering practices for dependable, production-grade AI systems.', 'https://images.unsplash.com/photo-1555949963-aa79dcee981c?w=800&q=80', 5, 1050, 'published', '2026-08-15 06:56:07.542587+00', 280, 41, 4, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["AI"]', '''ai'':4A,7B,15C,81,131 ''ai-pow'':3A ''appli'':158 ''applic'':6A,25,82 ''augment'':92 ''build'':1A,24 ''busi'':88 ''care'':59 ''catch'':118 ''challeng'':38 ''consist'':104 ''content'':19,22,77,127 ''cost'':111 ''dataset'':142 ''day'':148 ''depend'':11C,57,135 ''design'':61,144 ''differ'':53 ''disciplin'':159 ''doc'':18 ''engin'':8C,37,161 ''equal'':107 ''evalu'':97 ''fallback'':66 ''final'':129 ''generat'':93 ''golden'':141 ''grace'':65 ''grade'':14C ''ground'':102 ''help'':99 ''import'':108 ''inher'':165 ''input'':50 ''introduc'':32 ''keep'':100 ''languag'':30 ''larg'':29 ''latenc'':110 ''let'':116 ''like'':132 ''logic'':89 ''mean'':47 ''model'':31,42,70,85 ''monitor'':105 ''new'':34 ''nondeterminist'':166 ''observ'':146 ''one'':149,156 ''output'':43,62,95 ''paragraph'':21,76,126 ''pipelin'':98 ''power'':5A ''practic'':9C,162 ''probabilist'':45 ''produc'':52 ''product'':13C ''production-grad'':12C ''prompt'':60,138 ''qualiti'':113 ''regress'':119 ''reli'':27 ''reliabl'':2A,55 ''respons'':101 ''result'':54 ''retriev'':91 ''retrieval-aug'':90 ''robust'':80 ''separ'':83 ''set'':35 ''softwar'':41,160 ''strategi'':67 ''structur'':94 ''succeed'':153 ''system'':16C ''team'':117,151 ''technolog'':167 ''test'':139 ''text'':23,74,78,124,128,169 ''therefor'':56 ''time'':115 ''track'':109 ''tradit'':40 ''treat'':130 ''type'':17,20,73,75,123,125,168 ''uncertain'':72 ''unlik'':39 ''user'':121 ''valid'':63 ''version'':136', 0, NULL);
