INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000020', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-physics-of-black-holes', 'The Physics of Black Holes', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Black holes are regions of space where gravity is so strong that nothing, not even light, can escape. They form when massive stars collapse at the end of their lives, compressing enormous amounts of matter into an incredibly small space. The boundary beyond which escape is impossible is called the event horizon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite their name, black holes are not empty. They are among the most energetic objects in the universe, and matter falling into them heats up and emits intense radiation. Supermassive black holes, millions or billions of times the mass of the sun, sit at the centers of most galaxies.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Black holes also test the limits of our understanding of physics. They sit at the intersection of general relativity and quantum mechanics, two theories that have not yet been fully reconciled. Studying them may reveal deeper truths about the nature of space, time, and information.", "type": "text"}]}]}', 'The extreme objects that challenge our understanding of the universe.', 'https://images.unsplash.com/photo-1465101162946-4377e57745c3?w=800&q=80', 5, 940, 'published', '2026-08-12 06:56:07.542587+00', 330, 50, 9, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Science"]', '''also'':139 ''among'':92 ''amount'':56 ''beyond'':66 ''billion'':116 ''black'':4A,24,85,112,137 ''boundari'':65 ''call'':72 ''center'':127 ''challeng'':11C ''collaps'':47 ''compress'':54 ''content'':19,22,80,135 ''deeper'':172 ''despit'':82 ''doc'':18 ''emit'':108 ''empti'':89 ''end'':50 ''energet'':95 ''enorm'':55 ''escap'':41,68 ''even'':38 ''event'':74 ''extrem'':8C ''fall'':102 ''form'':43 ''fulli'':16