INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000023', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'the-social-lives-of-elephants', 'The Social Lives of Elephants', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Elephants are among the most social animals on the planet. They live in tight-knit family groups led by a matriarch, and they form bonds that can last a lifetime. Their social intelligence is reflected in their ability to cooperate, comfort one another, and even mourn their dead.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Communication is central to elephant society. They use a rich repertoire of sounds, from low-frequency rumbles that travel for kilometers to trumpets and tactile gestures. These signals help them coordinate movement, warn of danger, and maintain relationships across vast distances.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Elephants also play a vital ecological role. As they move, they shape the landscape, disperse seeds, and create water sources used by other animals. Protecting elephants means protecting the health of entire ecosystems.", "type": "text"}]}]}', 'The complex family bonds and communication of the world''s largest land animal.', 'https://images.unsplash.com/photo-1555949963-aa79dcee981c?w=800&q=80', 4, 920, 'published', '2026-08-14 06:56:07.542587+00', 250, 39, 6, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Animals"]', '''abil'':65 ''across'':121 ''also'':131 ''among'':29 ''anim'':6B,19C,33,153 ''anoth'':70 ''bond'':10C,52 ''central'':84 ''comfort'':68 ''communic'':12C,82 ''complex'':8C ''content'':22,25,80,128 ''cooper'':67 ''coordin'':113 ''creat'':147 ''danger'':117 ''dead'':75 ''dispers'':144 ''distanc'':123 ''doc'':21 ''ecolog'':135 ''ecosystem'':162 ''eleph'':5A,27,86,130,155 ''entir'':161 ''even'':72 ''famili'':9C,43 ''form'':51 ''frequenc'':98 ''gestur'':108 ''group'':44 ''health'':159 ''help'':111 ''intellig'':60 ''kilomet'':103 ''knit'':42 ''land'':18C ''landscap'':143 ''largest'':17C ''last'':55 ''led'':45 ''lifetim'':57 ''live'':3A,38 ''low'':97 ''low-frequ'':96 ''maintain'':119 ''matriarch'':48 ''mean'':156 ''mourn'':73 ''move'':139 ''movement'':114 ''one'':69 ''paragraph'':24,79,127 ''planet'':36 ''play'':132 ''protect'':154,157 ''reflect'':62 ''relationship'':120 ''repertoir'':92 ''rich'':91 ''role'':136 ''rumbl'':99 ''seed'':145 ''shape'':141 ''signal'':110 ''social'':2A,32,59 ''societi'':87 ''sound'':94 ''sourc'':149 ''tactil'':107 ''text'':26,77,81,125,129,164 ''tight'':41 ''tight-knit'':40 ''travel'':101 ''trumpet'':105 ''type'':20,23,76,78,124,126,163 ''use'':89,150 ''vast'':122 ''vital'':134 ''warn'':115 ''water'':148 ''world'':15C', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000012', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'understanding-blockchain-beyond-cryptocurrency', 'Understanding Blockchain Beyond Cryptocurrency', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Blockchain is often associated with cryptocurrency, but the underlying technology has broader applications. At its core, a blockchain is a distributed ledger that records transactions in a way that is transparent, tamper-resistant, and verifiable without a central authority.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Supply chains are a natural fit. By recording each step of a product''s journey on a shared ledger, companies can verify authenticity, track provenance, and reduce fraud. Healthcare, real estate, and identity management are other areas exploring blockchain for secure, auditable record-keeping.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The technology is not a solution for every problem. Blockchains can be slower and more expensive than traditional databases, and many use cases do not actually require decentralization. The key is to understand the tradeoffs and apply blockchain only where its unique properties add real value.", "type": "text"}]}]}', 'The practical applications of distributed ledgers beyond digital currency.', 'https://images.unsplash.com/photo-1639762681485-074b7f938ba0?w=800&q=80', 5, 980, 'published', '2026-08-15 06:56:07.542587+00', 210, 33, 4, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Technology"]', '''actual'':144 ''add'':162 ''appli'':155 ''applic'':8C,34 ''area'':104 ''associ'':25 ''audit'':109 ''authent'':90 ''author'':61 ''beyond'':3A,12C ''blockchain'':2A,22,39,106,128,156 ''broader'':33 ''case'':141 ''central'':60 ''chain'':69 ''compani'':87 ''content'':17,20,66,117 ''core'':37 ''cryptocurr'':4A,27 ''currenc'':14C ''databas'':137 ''decentr'':146 ''digit'':13C ''distribut'':10C,42 ''doc'':16 ''estat'':98 ''everi'':126 ''expens'':134 ''explor'':105 ''fit'':73 ''fraud'':95 ''healthcar'':96 ''ident'':100 ''journey'':82 ''keep'':112 ''key'':148 ''ledger'':11C,43,86 ''manag'':101 ''mani'':139 ''natur'':72 ''often'':24 ''paragraph'':19,65,116 ''practic'':7C ''problem'':127 ''product'':80 ''properti'':161 ''proven'':92 ''real'':97,163 ''record'':45,75,111 ''record-keep'':110 ''reduc'':94 ''requir'':145 ''resist'':55 ''secur'':108 ''share'':85 ''slower'':131 ''solut'':124 ''step'':77 ''suppli'':68 ''tamper'':54 ''tamper-resist'':53 ''technolog'':5B,31,120 ''text'':21,63,67,114,118,166 ''track'':91 ''tradeoff'':153 ''tradit'':136 ''transact'':46 ''transpar'':52 ''type'':15,18,62,64,113,115,165 ''under'':30 ''understand'':1A,151 ''uniqu'':160 ''use'':140 ''valu'':164 ''verifi'':57,89 ''way'':49 ''without'':58', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000013', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-evolution-of-cloud-native-architecture', 'The Evolution of Cloud Native Architecture', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Cloud native architecture is an approach to building software that takes full advantage of cloud computing. It emphasizes containers, microservices, declarative infrastructure, and continuous delivery. The goal is to build systems that are scalable, resilient, and easy to change.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The journey began with virtual machines, then moved to containers and orchestration platforms like Kubernetes. Along the way, practices such as service meshes, observability, and GitOps emerged to manage the growing complexity of distributed systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The next frontier is serverless and platform engineering, which abstract away even more infrastructure. Teams increasingly focus on business logic while the platform handles scaling, security, and reliability. The result is faster delivery and more resilient applications.", "type": "text"}]}]}', 'How modern software architecture has evolved to embrace the cloud.', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&q=80', 5, 960, 'published', '2026-08-14 06:56:07.542587+00', 250, 39, 6, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Technology"]', '''abstract'':120 ''advantag'':37 ''along'':85 ''applic'':147 ''approach'':30 ''architectur'':6A,11C,27 ''away'':121 ''began'':72 ''build'':32,54 ''busi'':129 ''chang'':63 ''cloud'':4A,17C,25,39 ''complex'':101 ''comput'':40 ''contain'':43,79 ''content'':20,23,68,109 ''continu'':48 ''declar'':45 ''deliveri'':49,143 ''distribut'':103 ''doc'':19 ''easi'':61 ''embrac'':15C ''emerg'':96 ''emphas'':42 ''engin'':118 ''even'':122 ''evolut'':2A ''evolv'':13C ''faster'':142 ''focus'':127 ''frontier'':113 ''full'':36 ''gitop'':95 ''goal'':51 ''grow'':100 ''handl'':134 ''increas'':126 ''infrastructur'':46,124 ''journey'':71 ''kubernet'':84 ''like'':83 ''logic'':130 ''machin'':75 ''manag'':98 ''mesh'':92 ''microservic'':44 ''modern'':9C ''move'':77 ''nativ'':5A,26 ''next'':112 ''observ'':93 ''orchestr'':81 ''paragraph'':22,67,108 ''platform'':82,117,133 ''practic'':88 ''reliabl'':138 ''resili'':59,146 ''result'':140 ''scalabl'':58 ''scale'':135 ''secur'':136 ''serverless'':115 ''servic'':91 ''softwar'':10C,33 ''system'':55,104 ''take'':35 ''team'':125 ''technolog'':7B ''text'':24,65,69,106,110,149 ''type'':18,21,64,66,105,107,148 ''virtual'':74 ''way'':87', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000014', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'quantum-computing-a-practical-overview', 'Quantum Computing: A Practical Overview', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Quantum computing uses the principles of quantum mechanics to process information in ways that classical computers cannot. Instead of bits that are either zero or one, quantum computers use qubits that can exist in superpositions of states. This allows them to explore many possibilities simultaneously.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The technology is still in its early stages, but it holds promise for specific problems such as simulating molecules, optimizing complex systems, and breaking certain cryptographic schemes. These are problems where classical computers struggle, even at enormous scale.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Practical quantum computers face significant engineering challenges, including error correction and maintaining qubit stability. Progress is steady, however, and researchers are already developing quantum algorithms and hybrid approaches that combine quantum and classical computing.", "type": "text"}]}]}', 'What quantum computing is and the problems it may one day solve.', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=800&q=80', 5, 940, 'published', '2026-08-13 06:56:07.542587+00', 230, 36, 5, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Technology"]', '''algorithm'':145 ''allow'':64 ''alreadi'':142 ''approach'':148 ''bit'':45 ''break'':100 ''cannot'':42 ''certain'':101 ''challeng'':127 ''classic'':40,108,153 ''combin'':150 ''complex'':97 ''comput'':2A,9C,27,41,53,109,123,154 ''content'':21,24,75,119 ''correct'':130 ''cryptograph'':102 ''day'':17C ''develop'':143 ''doc'':20 ''earli'':83 ''either'':48 ''engin'':126 ''enorm'':113 ''error'':129 ''even'':111 ''exist'':58 ''explor'':67 ''face'':124 ''hold'':87 ''howev'':138 ''hybrid'':147 ''includ'':128 ''inform'':36 ''instead'':43 ''maintain'':132 ''mani'':68 ''may'':15C ''mechan'':33 ''molecul'':95 ''one'':16C,51 ''optim'':96 ''overview'':5A ''paragraph'':23,74,118 ''possibl'':69 ''practic'':4A,121 ''principl'':30 ''problem'':13C,91,106 ''process'':35 ''progress'':135 ''promis'':88 ''quantum'':1A,8C,26,32,52,122,144,151 ''qubit'':55,133 ''research'':140 ''scale'':114 ''scheme'':103 ''signific'':125 ''simul'':94 ''simultan'':70 ''solv'':18C ''specif'':90 ''stabil'':134 ''stage'':84 ''state'':62 ''steadi'':137 ''still'':80 ''struggl'':110 ''superposit'':60 ''system'':98 ''technolog'':6B,78 ''text'':25,72,76,116,120,156 ''type'':19,22,71,73,115,117,155 ''use'':28,54 ''way'':38 ''zero'':49', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000015', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'the-future-of-5g-and-connectivity', 'The Future of 5G and Connectivity', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "5G is more than just faster mobile internet. It brings lower latency, higher capacity, and the ability to connect far more devices simultaneously. These capabilities enable new applications, from augmented reality and remote surgery to smart cities and connected vehicles.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The real impact of 5G lies in its ability to support the Internet of Things at scale. Industrial sensors, autonomous systems, and real-time monitoring all benefit from reliable, low-latency connections. This is transforming manufacturing, logistics, and public infrastructure.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Looking further ahead, research into 6G is already underway, promising even greater speeds and integration with satellite networks. The goal is ubiquitous connectivity that reaches every corner of the globe, closing the digital divide and enabling innovations we have not yet imagined.", "type": "text"}]}]}', 'How next-generation networks are enabling new kinds of applications.', 'https://images.unsplash.com/photo-1548865164-c4e3ca63de0e?w=800&q=80', 5, 900, 'published', '2026-08-12 06:56:07.542587+00', 200, 31, 3, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Technology"]', '''5g'':4A,26,76 ''6g'':125 ''abil'':42,80 ''ahead'':122 ''alreadi'':127 ''applic'':18C,53 ''augment'':55 ''autonom'':91 ''benefit'':99 ''bring'':35 ''capabl'':50 ''capac'':39 ''citi'':62 ''close'':150 ''connect'':6A,44,64,105,142 ''content'':21,24,70,118 ''corner'':146 ''devic'':47 ''digit'':152 ''divid'':153 ''doc'':20 ''enabl'':14C,51,155 ''even'':130 ''everi'':145 ''far'':45 ''faster'':31 ''futur'':2A ''generat'':11C ''globe'':149 ''goal'':139 ''greater'':131 ''higher'':38 ''imagin'':161 ''impact'':74 ''industri'':89 ''infrastructur'':113 ''innov'':156 ''integr'':134 ''internet'':33,84 ''kind'':16C ''latenc'':37,104 ''lie'':77 ''logist'':110 ''look'':120 ''low'':103 ''low-lat'':102 ''lower'':36 ''manufactur'':109 ''mobil'':32 ''monitor'':97 ''network'':12C,137 ''new'':15C,52 ''next'':10C ''next-gener'':9C ''paragraph'':23,69,117 ''promis'':129 ''public'':112 ''reach'':144 ''real'':73,95 ''real-tim'':94 ''realiti'':56 ''reliabl'':101 ''remot'':58 ''research'':123 ''satellit'':136 ''scale'':88 ''sensor'':90 ''simultan'':48 ''smart'':61 ''speed'':132 ''support'':82 ''surgeri'':59 ''system'':92 ''technolog'':7B ''text'':25,67,71,115,119,163 ''thing'':86 ''time'':96 ''transform'':108 ''type'':19,22,66,68,114,116,162 ''ubiquit'':141 ''underway'':128 ''vehicl'':65 ''yet'':160', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000016', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-mysteries-of-dark-matter', 'The Mysteries of Dark Matter', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dark matter is one of the greatest mysteries in modern physics. It does not emit, absorb, or reflect light, yet its gravitational influence is felt throughout the universe. Astronomers infer its existence from the way galaxies rotate and how light bends around massive objects.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Current estimates suggest that dark matter makes up about a quarter of the universe''s total energy, far more than the ordinary matter we can see. Despite decades of searching, its fundamental nature remains unknown. Leading candidates include weakly interacting massive particles and axions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Detecting dark matter is extraordinarily difficult because it interacts so weakly with ordinary matter. Experiments deep underground and in space are searching for the faintest signals. Solving this mystery would reshape our understanding of the cosmos.", "type": "text"}]}]}', 'The invisible substance that shapes the universe and how scientists hunt for it.', 'https://images.unsplash.com/photo-1462331940025-496dfbfc7564?w=800&q=80', 5, 950, 'published', '2026-08-16 06:56:07.542587+00', 260, 40, 6, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Science"]', '''absorb'':40 ''around'':66 ''astronom'':53 ''axion'':118 ''bend'':65 ''candid'':111 ''content'':20,23,73,123 ''cosmos'':160 ''current'':75 ''dark'':4A,25,79,126 ''decad'':102 ''deep'':140 ''despit'':101 ''detect'':125 ''difficult'':130 ''doc'':19 ''emit'':39 ''energi'':91 ''estim'':76 ''exist'':56 ''experi'':139 ''extraordinarili'':129 ''faintest'':149 ''far'':92 ''felt'':49 ''fundament'':106 ''galaxi'':60 ''gravit'':46 ''greatest'':31 ''hunt'':17C ''includ'':112 ''infer'':54 ''influenc'':47 ''interact'':114,133 ''invis'':8C ''lead'':110 ''light'':43,64 ''make'':81 ''massiv'':67,115 ''matter'':5A,26,80,97,127,138 ''modern'':34 ''mysteri'':2A,32,153 ''natur'':107 ''object'':68 ''one'':28 ''ordinari'':96,137 ''paragraph'':22,72,122 ''particl'':116 ''physic'':35 ''quarter'':85 ''reflect'':42 ''remain'':108 ''reshap'':155 ''rotat'':61 ''scienc'':6B ''scientist'':16C ''search'':104,146 ''see'':100 ''shape'':11C ''signal'':150 ''solv'':151 ''space'':144 ''substanc'':9C ''suggest'':77 ''text'':24,70,74,120,124,162 ''throughout'':50 ''total'':90 ''type'':18,21,69,71,119,121,161 ''underground'':141 ''understand'':157 ''univers'':13C,52,88 ''unknown'':109 ''way'':59 ''weak'':113,135 ''would'':154 ''yet'':44', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000017', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'crispr-and-the-future-of-gene-editing', 'CRISPR and the Future of Gene Editing', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "CRISPR is a revolutionary gene-editing tool that allows scientists to make precise changes to DNA. Adapted from a natural defense mechanism in bacteria, it uses a guide molecule to locate a specific sequence and an enzyme to cut it. This makes genetic modification faster, cheaper, and more accurate than ever before.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The potential applications are vast. CRISPR is being used to develop disease-resistant crops, study genetic disorders, and explore treatments for conditions such as sickle cell disease. Clinical trials are already underway for several therapies.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The technology also raises profound ethical questions, particularly around editing human embryos and the possibility of unintended consequences. As the science advances, society must carefully weigh the benefits against the risks and establish thoughtful guidelines.", "type": "text"}]}]}', 'How a bacterial defense system became a powerful tool for editing life.', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=800&q=80', 5, 980, 'published', '2026-08-15 06:56:07.542587+00', 310, 47, 8, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Science"]', '''accur'':77 ''adapt'':45 ''advanc'':150 ''allow'':37 ''alreadi'':118 ''also'':131 ''applic'':89 ''around'':137 ''bacteri'':11C ''bacteria'':52 ''becam'':14C ''benefit'':156 ''care'':153 ''cell'':113 ''chang'':42 ''cheaper'':74 ''clinic'':115 ''condit'':109 ''consequ'':146 ''content'':23,26,85,127 ''crispr'':1A,28,92 ''crop'':101 ''cut'':67 ''defens'':12C,49 ''develop'':97 ''diseas'':99,114 ''disease-resist'':98 ''disord'':104 ''dna'':44 ''doc'':22 ''edit'':7A,19C,34,138 ''embryo'':140 ''enzym'':65 ''establish'':161 ''ethic'':134 ''ever'':79 ''explor'':106 ''faster'':73 ''futur'':4A ''gene'':6A,33 ''gene-edit'':32 ''genet'':71,103 ''guid'':56 ''guidelin'':163 ''human'':139 ''life'':20C ''locat'':59 ''make'':40,70 ''mechan'':50 ''modif'':72 ''molecul'':57 ''must'':152 ''natur'':48 ''paragraph'':25,84,126 ''particular'':136 ''possibl'':143 ''potenti'':88 ''power'':16C ''precis'':41 ''profound'':133 ''question'':135 ''rais'':132 ''resist'':100 ''revolutionari'':31 ''risk'':159 ''scienc'':8B,149 ''scientist'':38 ''sequenc'':62 ''sever'':121 ''sickl'':112 ''societi'':151 ''specif'':61 ''studi'':102 ''system'':13C ''technolog'':130 ''text'':27,82,86,124,128,165 ''therapi'':122 ''thought'':162 ''tool'':17C,35 ''treatment'':107 ''trial'':116 ''type'':21,24,81,83,123,125,164 ''underway'':119 ''unintend'':145 ''use'':54,95 ''vast'':91 ''weigh'':154', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000018', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'the-human-microbiome-our-invisible-ecosystem', 'The Human Microbiome: Our Invisible Ecosystem', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The human body is home to trillions of microorganisms, collectively known as the microbiome. These bacteria, viruses, and fungi live on our skin and in our gut, and they play a crucial role in digestion, immunity, and even mental health. In many ways, we are walking ecosystems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Research has linked the gut microbiome to a wide range of health outcomes, from metabolic disorders to mood. A diverse microbiome is generally associated with better health, while imbalances have been connected to conditions such as obesity, allergies, and inflammatory diseases.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Diet, lifestyle, and medication all shape the microbiome. Fermented foods, fiber, and a varied diet support microbial diversity. As scientists learn more, the microbiome is emerging as a promising target for new therapies and personalized medicine.", "type": "text"}]}]}', 'The trillions of microbes that live in and on us and why they matter.', 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&q=80', 5, 920, 'published', '2026-08-14 06:56:07.542587+00', 240, 38, 5, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Science"]', '''allergi'':119 ''associ'':105 ''bacteria'':44 ''better'':107 ''bodi'':31 ''collect'':38 ''condit'':115 ''connect'':113 ''content'':24,27,80,127 ''crucial'':60 ''diet'':129,143 ''digest'':63 ''diseas'':122 ''disord'':97 ''divers'':101,146 ''doc'':23 ''ecosystem'':6A,75 ''emerg'':154 ''even'':66 ''ferment'':137 ''fiber'':139 ''food'':138 ''fungi'':47 ''general'':104 ''gut'':55,86 ''health'':68,93,108 ''home'':33 ''human'':2A,30 ''imbal'':110 ''immun'':64 ''inflammatori'':121 ''invis'':5A ''known'':39 ''learn'':149 ''lifestyl'':130 ''link'':84 ''live'':13C,48 ''mani'':70 ''matter'':21C ''medic'':132 ''medicin'':164 ''mental'':67 ''metabol'':96 ''microb'':11C ''microbi'':145 ''microbiom'':3A,42,87,102,136,152 ''microorgan'':37 ''mood'':99 ''new'':160 ''obes'':118 ''outcom'':94 ''paragraph'':26,79,126 ''person'':163 ''play'':58 ''promis'':157 ''rang'':91 ''research'':82 ''role'':61 ''scienc'':7B ''scientist'':148 ''shape'':134 ''skin'':51 ''support'':144 ''target'':158 ''text'':28,77,81,124,128,166 ''therapi'':161 ''trillion'':9C,35 ''type'':22,25,76,78,123,125,165 ''us'':17C ''vari'':142 ''virus'':45 ''walk'':74 ''way'':71 ''wide'':90', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000019', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'climate-science-what-the-data-tells-us', 'Climate Science: What the Data Tells Us', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Climate science is built on decades of careful measurement. Temperature records, ice cores, and satellite observations all tell a consistent story: the planet is warming, and human activity is the primary driver. The concentration of carbon dioxide in the atmosphere is higher than at any point in hundreds of thousands of years.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The consequences are already visible. Sea levels are rising, glaciers are retreating, and extreme weather events are becoming more frequent and intense. These changes affect agriculture, water supplies, and human health, with the greatest impacts falling on the most vulnerable communities.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The science also points to solutions. Reducing emissions, transitioning to renewable energy, and protecting natural carbon sinks can limit future warming. The challenge is not a lack of knowledge but the collective will to act on it.", "type": "text"}]}]}', 'What the evidence says about a warming planet and the path forward.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&q=80', 5, 960, 'published', '2026-08-13 06:56:07.542587+00', 290, 44, 7, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Science"]', '''act'':167 ''activ'':55 ''affect'':110 ''agricultur'':111 ''alreadi'':89 ''also'':135 ''atmospher'':67 ''becom'':103 ''built'':31 ''carbon'':63,148 ''care'':35 ''challeng'':155 ''chang'':109 ''climat'':1A,28 ''collect'':164 ''communiti'':126 ''concentr'':61 ''consequ'':87 ''consist'':47 ''content'':23,26,84,131 ''core'':40 ''data'':5A ''decad'':33 ''dioxid'':64 ''doc'':22 ''driver'':59 ''emiss'':140 ''energi'':144 ''event'':101 ''evid'':11C ''extrem'':99 ''fall'':121 ''forward'':20C ''frequent'':105 ''futur'':152 ''glacier'':95 ''greatest'':119 ''health'':116 ''higher'':69 ''human'':54,115 ''hundr'':75 ''ice'':39 ''impact'':120 ''intens'':107 ''knowledg'':161 ''lack'':159 ''level'':92 ''limit'':151 ''measur'':36 ''natur'':147 ''observ'':43 ''paragraph'':25,83,130 ''path'':19C ''planet'':16C,50 ''point'':73,136 ''primari'':58 ''protect'':146 ''record'':38 ''reduc'':139 ''renew'':143 ''retreat'':97 ''rise'':94 ''satellit'':42 ''say'':12C ''scienc'':2A,8B,29,134 ''sea'':91 ''sink'':149 ''solut'':138 ''stori'':48 ''suppli'':113 ''tell'':6A,45 ''temperatur'':37 ''text'':27,81,85,128,132,171 ''thousand'':77 ''transit'':141 ''type'':21,24,80,82,127,129,170 ''us'':7A ''visibl'':90 ''vulner'':125 ''warm'':15C,52,153 ''water'':112 ''weather'':100 ''year'':79', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000021', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-intelligence-of-octopuses', 'The Intelligence of Octopuses', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Octopuses are among the most intelligent invertebrates on Earth. They can solve puzzles, open jars, navigate mazes, and even use tools. Their intelligence evolved independently from that of vertebrates, making them a fascinating case study in how complex cognition can arise.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Much of an octopus''s nervous system is distributed throughout its arms, which can act semi-independently. This unusual architecture allows them to multitask in ways that are hard for us to imagine. They are also masters of camouflage, changing color and texture in an instant.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Octopuses are curious and playful, and they have been observed recognizing individual humans. Their short lifespans and solitary nature make them difficult to study, but each new discovery reveals a mind that is both alien and surprisingly familiar.", "type": "text"}]}]}', 'The remarkable problem-solving abilities of these eight-armed creatures.', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?w=800&q=80', 4, 900, 'published', '2026-08-16 06:56:07.542587+00', 280, 43, 7, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Animals"]', '''abil'':11C ''act'':86 ''alien'':159 ''allow'':93 ''also'':108 ''among'':27 ''anim'':5B ''architectur'':92 ''aris'':65 ''arm'':16C,83 ''camouflag'':111 ''case'':58 ''chang'':112 ''cognit'':63 ''color'':113 ''complex'':62 ''content'':20,23,70,123 ''creatur'':17C ''curious'':127 ''difficult'':146 ''discoveri'':152 ''distribut'':80 ''doc'':19 ''earth'':33 ''eight'':15C ''eight-arm'':14C ''even'':43 ''evolv'':48 ''familiar'':162 ''fascin'':57 ''hard'':101 ''human'':137 ''imagin'':105 ''independ'':49,89 ''individu'':136 ''instant'':118 ''intellig'':2A,30,47 ''invertebr'':31 ''jar'':39 ''lifespan'':140 ''make'':54,144 ''master'':109 ''maze'':41 ''mind'':155 ''much'':72 ''multitask'':96 ''natur'':143 ''navig'':40 ''nervous'':77 ''new'':151 ''observ'':134 ''octopus'':4A,25,75,125 ''open'':38 ''paragraph'':22,69,122 ''play'':129 ''problem'':9C ''problem-solv'':8C ''puzzl'':37 ''recogn'':135 ''remark'':7C ''reveal'':153 ''semi'':88 ''semi-independ'':87 ''short'':139 ''solitari'':142 ''solv'':10C,36 ''studi'':59,148 ''surpris'':161 ''system'':78 ''text'':24,67,71,120,124,164 ''textur'':115 ''throughout'':81 ''tool'':45 ''type'':18,21,66,68,119,121,163 ''unusu'':91 ''us'':103 ''use'':44 ''vertebr'':53 ''way'':98', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000022', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'migratory-birds-natures-navigators', 'Migratory Birds: Nature''s Navigators', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every year, billions of birds undertake extraordinary journeys across continents and oceans. Some species travel tens of thousands of kilometers between breeding and wintering grounds, navigating with remarkable precision. How they do it remains one of nature''s great wonders.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Migratory birds use a combination of cues to find their way. They read the position of the sun and stars, sense the Earth''s magnetic field, and recognize landmarks. Some species even use their sense of smell to navigate. These abilities are refined over generations of evolution.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Migration is increasingly threatened by habitat loss, climate change, and human development. Protecting the stopover sites and flyways that birds depend on is essential to their survival. Their journeys connect ecosystems across the globe and remind us how interconnected life truly is.", "type": "text"}]}]}', 'The incredible navigational feats of birds on the move.', 'https://images.unsplash.com/photo-1473968512647-3e447244af8f?w=800&q=80', 4, 880, 'published', '2026-08-15 06:56:07.542587+00', 210, 32, 4, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Animals"]', '''abil'':109 ''across'':31,153 ''anim'':6B ''billion'':25 ''bird'':2A,12C,27,70,141 ''breed'':44 ''chang'':130 ''climat'':129 ''combin'':73 ''connect'':151 ''content'':18,21,67,120 ''contin'':32 ''cue'':75 ''depend'':142 ''develop'':133 ''doc'':17 ''earth'':91 ''ecosystem'':152 ''essenti'':145 ''even'':100 ''everi'':23 ''evolut'':115 ''extraordinari'':29 ''feat'':10C ''field'':94 ''find'':77 ''flyway'':139 ''generat'':113 ''globe'':155 ''great'':61 ''ground'':47 ''habitat'':127 ''human'':132 ''increas'':124 ''incred'':8C ''interconnect'':160 ''journey'':30,150 ''kilomet'':42 ''landmark'':97 ''life'':161 ''loss'':128 ''magnet'':93 ''migrat'':122 ''migratori'':1A,69 ''move'':15C ''natur'':3A,59 ''navig'':5A,9C,48,107 ''ocean'':34 ''one'':57 ''paragraph'':20,66,119 ''posit'':83 ''precis'':51 ''protect'':134 ''read'':81 ''recogn'':96 ''refin'':111 ''remain'':56 ''remark'':50 ''remind'':157 ''sens'':89,103 ''site'':137 ''smell'':105 ''speci'':36,99 ''star'':88 ''stopov'':136 ''sun'':86 ''surviv'':148 ''ten'':38 ''text'':22,64,68,117,121,165 ''thousand'':40 ''threaten'':125 ''travel'':37 ''truli'':162 ''type'':16,19,63,65,116,118,164 ''undertak'':28 ''us'':158 ''use'':71,101 ''way'':79 ''winter'':46 ''wonder'':62 ''year'':24', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000024', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13', 'deep-sea-creatures-life-in-the-abyss', 'Deep Sea Creatures: Life in the Abyss', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The deep sea is the largest habitat on Earth, yet it remains one of the least explored. In the crushing darkness thousands of meters below the surface, life has evolved in astonishing ways. Many creatures produce their own light through bioluminescence to hunt, communicate, and evade predators.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Survival in the abyss requires extreme adaptations. Some animals have enormous mouths and expandable stomachs to make the most of scarce food. Others rely on chemosynthesis, drawing energy from chemicals released by hydrothermal vents rather than from sunlight.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Each expedition to the deep sea reveals new species and behaviors that challenge our assumptions about where life can thrive. These ecosystems are fragile and increasingly threatened by deep-sea mining and climate change, making their study and protection more urgent than ever.", "type": "text"}]}]}', 'The strange and wonderful life that thrives in the ocean''s depths.', 'https://images.unsplash.com/photo-1532153975070-2e9ab71f1b14?w=800&q=80', 4, 940, 'published', '2026-08-13 06:56:07.542587+00', 300, 46, 8, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Animals"]', '''abyss'':7A,84 ''adapt'':87 ''anim'':8B,89 ''assumpt'':139 ''astonish'':59 ''behavior'':135 ''bioluminesc'':68 ''challeng'':137 ''chang'':159 ''chemic'':110 ''chemosynthesi'':106 ''climat'':158 ''communic'':71 ''content'':23,26,79,123 ''creatur'':3A,62 ''crush'':47 ''dark'':48 ''deep'':1A,29,129,154 ''deep-sea'':153 ''depth'':20C ''doc'':22 ''draw'':107 ''earth'':36 ''ecosystem'':146 ''energi'':108 ''enorm'':91 ''evad'':73 ''ever'':168 ''evolv'':57 ''expand'':94 ''expedit'':126 ''explor'':44 ''extrem'':86 ''food'':102 ''fragil'':148 ''habitat'':34 ''hunt'':70 ''hydrotherm'':113 ''increas'':150 ''largest'':33 ''least'':43 ''life'':4A,13C,55,142 ''light'':66 ''make'':97,160 ''mani'':61 ''meter'':51 ''mine'':156 ''mouth'':92 ''new'':132 ''ocean'':18C ''one'':40 ''other'':103 ''paragraph'':25,78,122 ''predat'':74 ''produc'':63 ''protect'':164 ''rather'':115 ''releas'':111 ''reli'':104 ''remain'':39 ''requir'':85 ''reveal'':131 ''scarc'':101 ''sea'':2A,30,130,155 ''speci'':133 ''stomach'':95 ''strang'':10C ''studi'':162 ''sunlight'':118 ''surfac'':54 ''surviv'':81 ''text'':27,76,80,120,124,170 ''thousand'':49 ''threaten'':151 ''thrive'':15C,144 ''type'':21,24,75,77,119,121,169 ''urgent'':166 ''vent'':114 ''way'':60 ''wonder'':12C ''yet'':37', 0, NULL);
INSERT INTO public.posts VALUES ('10000000-0000-0000-0000-000000000025', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-remarkable-world-of-bees', 'The Remarkable World of Bees', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bees are essential to life on Earth. As pollinators, they are responsible for the reproduction of a huge share of the plants we rely on for food. Without them, many fruits, vegetables, and nuts would become scarce or disappear entirely.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A honeybee colony is a marvel of organization. Tens of thousands of individuals work together, communicating through the famous waggle dance to share the location of flowers. Each bee has a role, from foraging and nursing to guarding the hive, and the colony functions as a single superorganism.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bee populations face serious threats from habitat loss, pesticides, and disease. Supporting pollinators by planting native flowers, reducing chemical use, and protecting wild habitats is one of the most direct ways individuals can help the environment.", "type": "text"}]}]}', 'Why bees matter and the intricate societies they build.', 'https://images.unsplash.com/photo-1568526381923-caf3fd520382?w=800&q=80', 4, 900, 'published', '2026-08-12 06:56:07.542587+00', 270, 41, 5, false, '2026-08-17 06:56:07.542587+00', '2026-08-17 06:56:07.542587+00', 0, '["Animals"]', '''anim'':6B ''becom'':58 ''bee'':5A,8C,23,97,123 ''build'':15C ''chemic'':141 ''coloni'':71,111 ''communic'':84 ''content'':18,21,67,121 ''danc'':89 ''direct'':152 ''disappear'':61 ''diseas'':133 ''doc'':17 ''earth'':29 ''entir'':62 ''environ'':158 ''essenti'':25 ''face'':125 ''famous'':87 ''flower'':95,139 ''food'':49 ''forag'':102 ''fruit'':53 ''function'':112 ''guard'':106 ''habitat'':129,146 ''help'':156 ''hive'':108 ''honeybe'':70 ''huge'':40 ''individu'':81,154 ''intric'':12C ''life'':27 ''locat'':93 ''loss'':130 ''mani'':52 ''marvel'':74 ''matter'':9C ''nativ'':138 ''nurs'':104 ''nut'':56 ''one'':148 ''organ'':76 ''paragraph'':20,66,120 ''pesticid'':131 ''plant'':44,137 ''pollin'':31,135 ''popul'':124 ''protect'':144 ''reduc'':140 ''reli'':46 ''remark'':2A ''reproduct'':37 ''respons'':34 ''role'':100 ''scarc'':59 ''serious'':126 ''share'':41,91 ''singl'':115 ''societi'':13C ''superorgan'':116 ''support'':134 ''ten'':77 ''text'':22,64,68,118,122,160 ''thousand'':79 ''threat'':127 ''togeth'':83 ''type'':16,19,63,65,117,119,159 ''use'':142 ''veget'':54 ''waggl'':88 ''way'':153 ''wild'':145 ''without'':50 ''work'':82 ''world'':3A ''would'':57', 0, NULL);
INSERT INTO public.posts VALUES ('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'getting-started', 'Getting Started with IndieStack', '{"type": "doc"}', 'Learn how to get started with IndieStack.', 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?w=800&q=80', 5, 1200, 'published', '2026-07-30 11:55:14.106589+00', 150, 43, 0, false, '2026-07-30 11:55:14.106589+00', '2026-07-30 11:55:14.106589+00', 0, '[]', '''doc'':13 ''get'':1A,8C ''indiestack'':4A,11C ''learn'':5C ''start'':2A,9C ''type'':12', 0, NULL);
INSERT INTO public.posts VALUES ('dfb7e31b-2b92-41eb-88a4-3159f5113318', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12', 'the-joy-of-exploring-different-foods', 'The Joy of Exploring Different Foods', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Food is more than just something we eat; it is a reflection of culture, tradition, and creativity. Every region has its own unique flavors, ingredients, and cooking techniques that tell a story about its people. From spicy Indian curries and flavorful street food to Italian pasta and Japanese sushi, exploring different cuisines can be an exciting way to discover new tastes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trying new dishes can also turn an ordinary meal into an experience. Street food, homemade recipes, traditional dishes, and modern fusion cuisine each offer something different. Simple ingredients can be transformed into completely different meals depending on how they are prepared and combined. This variety is what makes food such an interesting part of everyday life.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Cooking and exploring food can also bring people together. Families often share recipes across generations, while friends gather around meals to celebrate special occasions or simply spend time together. Whether it is discovering a new restaurant, learning to cook a traditional dish, or enjoying a favorite meal at home, food has a unique ability to create memories and connect people.", "type": "text"}]}]}', 'food and technology', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80', 1, 177, 'published', '2026-08-17 07:21:15.743656+00', 0, 0, 0, false, '2026-08-17 07:21:15.743656+00', '2026-08-17 07:21:15.743656+00', 1, '["Food"]', '''abil'':200 ''across'':160 ''also'':89,152 ''around'':165 ''bring'':153 ''celebr'':168 ''combin'':127 ''complet'':117 ''connect'':205 ''content'':13,16,83,145 ''cook'':44,147,185 ''creat'':202 